#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
#[repr(u8)]
pub enum DamageType {
    Physical = 0,
    Fire = 1,
    Lightning = 2,
    Magic = 3,
    Acid = 4,
}
impl Default for DamageType {
    fn default() -> Self {
        DamageType::Physical
    }
}
impl DamageType {
    pub const fn from_repr(v: u8) -> Option<DamageType> {
        match v {
            0 => Some(DamageType::Physical),
            1 => Some(DamageType::Fire),
            2 => Some(DamageType::Lightning),
            3 => Some(DamageType::Magic),
            4 => Some(DamageType::Acid),
            _ => Option::None,
        }
    }
    /// Panics on a value that is not an enumerator (the C++ cast would be UB-adjacent).
    pub fn from_raw(v: u8) -> DamageType {
        Self::from_repr(v).unwrap_or_else(|| panic!("invalid DamageType {v}"))
    }
    pub const fn raw(self) -> u8 {
        self as u8
    }
}

