// spelldat.h
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Default, PartialOrd, Ord)]
pub struct SpellDataFlags(pub u8);
impl SpellDataFlags {
    pub const None_: SpellDataFlags = SpellDataFlags(0);
    pub const Fire: SpellDataFlags = SpellDataFlags(0);
    pub const Lightning: SpellDataFlags = SpellDataFlags(1);
    pub const Magic: SpellDataFlags = SpellDataFlags(2);
    pub const Targeted: SpellDataFlags = SpellDataFlags(4);
    pub const AllowedInTown: SpellDataFlags = SpellDataFlags(8);
    pub const fn has_any_of(self, f: Self) -> bool {
        self.0 & f.0 != 0
    }
    pub const fn has_none_of(self, f: Self) -> bool {
        self.0 & f.0 == 0
    }
    pub const fn has_all_of(self, f: Self) -> bool {
        self.0 & f.0 == f.0
    }
}
impl std::ops::BitOr for SpellDataFlags {
    type Output = SpellDataFlags;
    fn bitor(self, o: SpellDataFlags) -> SpellDataFlags {
        SpellDataFlags(self.0 | o.0)
    }
}
impl std::ops::BitOrAssign for SpellDataFlags {
    fn bitor_assign(&mut self, o: SpellDataFlags) {
        self.0 = self.0 | o.0;
    }
}
impl std::ops::BitAnd for SpellDataFlags {
    type Output = SpellDataFlags;
    fn bitand(self, o: SpellDataFlags) -> SpellDataFlags {
        SpellDataFlags(self.0 & o.0)
    }
}
impl std::ops::BitAndAssign for SpellDataFlags {
    fn bitand_assign(&mut self, o: SpellDataFlags) {
        self.0 = self.0 & o.0;
    }
}
impl std::ops::BitXor for SpellDataFlags {
    type Output = SpellDataFlags;
    fn bitxor(self, o: SpellDataFlags) -> SpellDataFlags {
        SpellDataFlags(self.0 ^ o.0)
    }
}
impl std::ops::BitXorAssign for SpellDataFlags {
    fn bitxor_assign(&mut self, o: SpellDataFlags) {
        self.0 = self.0 ^ o.0;
    }
}
impl std::ops::Not for SpellDataFlags {
    type Output = SpellDataFlags;
    fn not(self) -> SpellDataFlags {
        SpellDataFlags(!self.0)
    }
}

