#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Default, PartialOrd, Ord)]
pub struct ObjectDataFlags(pub u8);
impl ObjectDataFlags {
    pub const None_: ObjectDataFlags = ObjectDataFlags(0);
    pub const Animated: ObjectDataFlags = ObjectDataFlags(1);
    pub const Solid: ObjectDataFlags = ObjectDataFlags(2);
    pub const MissilesPassThrough: ObjectDataFlags = ObjectDataFlags(4);
    pub const Light: ObjectDataFlags = ObjectDataFlags(8);
    pub const Trap: ObjectDataFlags = ObjectDataFlags(16);
    pub const Breakable: ObjectDataFlags = ObjectDataFlags(32);
    pub const fn has_any_of(self, f: Self) -> bool {
        self.0 & f.0 != 0
    }
    pub const fn has_none_of(self, f: Self) -> bool {
        self.0 & f.0 == 0
    }
    pub const fn has_all_of(self, f: Self) -> bool {
        self.0 & f.0 == f.0
    }
}
impl std::ops::BitOr for ObjectDataFlags {
    type Output = ObjectDataFlags;
    fn bitor(self, o: ObjectDataFlags) -> ObjectDataFlags {
        ObjectDataFlags(self.0 | o.0)
    }
}
impl std::ops::BitOrAssign for ObjectDataFlags {
    fn bitor_assign(&mut self, o: ObjectDataFlags) {
        self.0 = self.0 | o.0;
    }
}
impl std::ops::BitAnd for ObjectDataFlags {
    type Output = ObjectDataFlags;
    fn bitand(self, o: ObjectDataFlags) -> ObjectDataFlags {
        ObjectDataFlags(self.0 & o.0)
    }
}
impl std::ops::BitAndAssign for ObjectDataFlags {
    fn bitand_assign(&mut self, o: ObjectDataFlags) {
        self.0 = self.0 & o.0;
    }
}
impl std::ops::BitXor for ObjectDataFlags {
    type Output = ObjectDataFlags;
    fn bitxor(self, o: ObjectDataFlags) -> ObjectDataFlags {
        ObjectDataFlags(self.0 ^ o.0)
    }
}
impl std::ops::BitXorAssign for ObjectDataFlags {
    fn bitxor_assign(&mut self, o: ObjectDataFlags) {
        self.0 = self.0 ^ o.0;
    }
}
impl std::ops::Not for ObjectDataFlags {
    type Output = ObjectDataFlags;
    fn not(self) -> ObjectDataFlags {
        ObjectDataFlags(!self.0)
    }
}

