// stores.h
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
#[repr(u8)]
pub enum TalkID {
    None = 0,
    Smith = 1,
    SmithBuy = 2,
    SmithSell = 3,
    SmithRepair = 4,
    Witch = 5,
    WitchBuy = 6,
    WitchSell = 7,
    WitchRecharge = 8,
    NoMoney = 9,
    NoRoom = 10,
    Confirm = 11,
    Boy = 12,
    BoyBuy = 13,
    Healer = 14,
    Storyteller = 15,
    HealerBuy = 16,
    StorytellerIdentify = 17,
    SmithPremiumBuy = 18,
    Gossip = 19,
    StorytellerIdentifyShow = 20,
    Tavern = 21,
    Drunk = 22,
    Barmaid = 23,
}
impl Default for TalkID {
    fn default() -> Self {
        TalkID::None
    }
}
impl TalkID {
    pub const fn from_repr(v: u8) -> Option<TalkID> {
        match v {
            0 => Some(TalkID::None),
            1 => Some(TalkID::Smith),
            2 => Some(TalkID::SmithBuy),
            3 => Some(TalkID::SmithSell),
            4 => Some(TalkID::SmithRepair),
            5 => Some(TalkID::Witch),
            6 => Some(TalkID::WitchBuy),
            7 => Some(TalkID::WitchSell),
            8 => Some(TalkID::WitchRecharge),
            9 => Some(TalkID::NoMoney),
            10 => Some(TalkID::NoRoom),
            11 => Some(TalkID::Confirm),
            12 => Some(TalkID::Boy),
            13 => Some(TalkID::BoyBuy),
            14 => Some(TalkID::Healer),
            15 => Some(TalkID::Storyteller),
            16 => Some(TalkID::HealerBuy),
            17 => Some(TalkID::StorytellerIdentify),
            18 => Some(TalkID::SmithPremiumBuy),
            19 => Some(TalkID::Gossip),
            20 => Some(TalkID::StorytellerIdentifyShow),
            21 => Some(TalkID::Tavern),
            22 => Some(TalkID::Drunk),
            23 => Some(TalkID::Barmaid),
            _ => Option::None,
        }
    }
    /// Panics on a value that is not an enumerator (the C++ cast would be UB-adjacent).
    pub fn from_raw(v: u8) -> TalkID {
        Self::from_repr(v).unwrap_or_else(|| panic!("invalid TalkID {v}"))
    }
    pub const fn raw(self) -> u8 {
        self as u8
    }
}

