// missiles.h
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
#[repr(u8)]
pub enum Direction16 {
    South = 0,
    South_SouthWest = 1,
    SouthWest = 2,
    West_SouthWest = 3,
    West = 4,
    West_NorthWest = 5,
    NorthWest = 6,
    North_NorthWest = 7,
    North = 8,
    North_NorthEast = 9,
    NorthEast = 10,
    East_NorthEast = 11,
    East = 12,
    East_SouthEast = 13,
    SouthEast = 14,
    South_SouthEast = 15,
}
impl Default for Direction16 {
    fn default() -> Self {
        Direction16::South
    }
}
impl Direction16 {
    pub const fn from_repr(v: u8) -> Option<Direction16> {
        match v {
            0 => Some(Direction16::South),
            1 => Some(Direction16::South_SouthWest),
            2 => Some(Direction16::SouthWest),
            3 => Some(Direction16::West_SouthWest),
            4 => Some(Direction16::West),
            5 => Some(Direction16::West_NorthWest),
            6 => Some(Direction16::NorthWest),
            7 => Some(Direction16::North_NorthWest),
            8 => Some(Direction16::North),
            9 => Some(Direction16::North_NorthEast),
            10 => Some(Direction16::NorthEast),
            11 => Some(Direction16::East_NorthEast),
            12 => Some(Direction16::East),
            13 => Some(Direction16::East_SouthEast),
            14 => Some(Direction16::SouthEast),
            15 => Some(Direction16::South_SouthEast),
            _ => Option::None,
        }
    }
    /// Panics on a value that is not an enumerator (the C++ cast would be UB-adjacent).
    pub fn from_raw(v: u8) -> Direction16 {
        Self::from_repr(v).unwrap_or_else(|| panic!("invalid Direction16 {v}"))
    }
    pub const fn raw(self) -> u8 {
        self as u8
    }
}

