// engine/animationinfo.h
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Default, PartialOrd, Ord)]
pub struct AnimationDistributionFlags(pub u8);
impl AnimationDistributionFlags {
    pub const None_: AnimationDistributionFlags = AnimationDistributionFlags(0);
    pub const None: AnimationDistributionFlags = AnimationDistributionFlags(0);
    pub const ProcessAnimationPending: AnimationDistributionFlags = AnimationDistributionFlags(1);
    pub const SkipsDelayOfLastFrame: AnimationDistributionFlags = AnimationDistributionFlags(2);
    pub const RepeatedAction: AnimationDistributionFlags = AnimationDistributionFlags(4);
    pub const fn has_any_of(self, f: Self) -> bool {
        self.0 & f.0 != 0
    }
    pub const fn has_none_of(self, f: Self) -> bool {
        self.0 & f.0 == 0
    }
    pub const fn has_all_of(self, f: Self) -> bool {
        self.0 & f.0 == f.0
    }
}
impl std::ops::BitOr for AnimationDistributionFlags {
    type Output = AnimationDistributionFlags;
    fn bitor(self, o: AnimationDistributionFlags) -> AnimationDistributionFlags {
        AnimationDistributionFlags(self.0 | o.0)
    }
}
impl std::ops::BitOrAssign for AnimationDistributionFlags {
    fn bitor_assign(&mut self, o: AnimationDistributionFlags) {
        self.0 = self.0 | o.0;
    }
}
impl std::ops::BitAnd for AnimationDistributionFlags {
    type Output = AnimationDistributionFlags;
    fn bitand(self, o: AnimationDistributionFlags) -> AnimationDistributionFlags {
        AnimationDistributionFlags(self.0 & o.0)
    }
}
impl std::ops::BitAndAssign for AnimationDistributionFlags {
    fn bitand_assign(&mut self, o: AnimationDistributionFlags) {
        self.0 = self.0 & o.0;
    }
}
impl std::ops::BitXor for AnimationDistributionFlags {
    type Output = AnimationDistributionFlags;
    fn bitxor(self, o: AnimationDistributionFlags) -> AnimationDistributionFlags {
        AnimationDistributionFlags(self.0 ^ o.0)
    }
}
impl std::ops::BitXorAssign for AnimationDistributionFlags {
    fn bitxor_assign(&mut self, o: AnimationDistributionFlags) {
        self.0 = self.0 ^ o.0;
    }
}
impl std::ops::Not for AnimationDistributionFlags {
    type Output = AnimationDistributionFlags;
    fn not(self) -> AnimationDistributionFlags {
        AnimationDistributionFlags(!self.0)
    }
}

